class Solution { public int countDigitOne(int n) { if (n <= 0) return 0; long count = 0; long factor = 1; long low = 0; long curr = 0; long high = 0; while (n / factor != 0) { low = n % factor; curr = (n / factor) % 10; high = n / (factor * 10); if (curr == 0) { count += high * factor; } else if (curr == 1) { count += high * factor + low + 1; } else { count += (high + 1) * factor; } factor *= 10; } return (int) count; } }